  "bg-shape-grid-fade": ".bg-shape-grid-fade::before {\r\n  inset: 0;\r\n  background-image:\r\n    linear-gradient(rgba(var(--bg-shape-color), 0.22) 1px, transparent 1px),\r\n    linear-gradient(90deg, rgba(var(--bg-shape-color), 0.22) 1px, transparent 1px);\r\n  background-size: 3.25rem 3.25rem;\r\n  mask-image: linear-gradient(to bottom, #000 0%, #000 42%, transparent 92%);\r\n  -webkit-mask-image: linear-gradient(to bottom, #000 0%, #000 42%, transparent 92%);\r\n}",
