  "bg-shape-grid-top-right": "/* Base Technical Grid Layer */\n.bg-shape-grid-top-right::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-top-right::after {\r\n  width: 36rem;\r\n  height: 36rem;\r\n  right: -12rem;\r\n  top: -19rem;\r\n  border-radius: 50%;\r\n  background: radial-gradient(\r\n    circle,\r\n    rgba(var(--bg-shape-color), 0.17) 0%,\r\n    rgba(var(--bg-shape-color), 0.07) 35%,\r\n    transparent 72%\r\n  );\r\n}",
  "bg-shape-grid-top-left": "/* Base Technical Grid Layer */\n.bg-shape-grid-top-left::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-top-left::after {\r\n  width: 36rem;\r\n  height: 36rem;\r\n  left: -14rem;\r\n  top: -20rem;\r\n  border-radius: 50%;\r\n  background: radial-gradient(\r\n    circle,\r\n    rgba(var(--bg-shape-color), 0.16),\r\n    rgba(var(--bg-shape-color), 0.05) 42%,\r\n    transparent 72%\r\n  );\r\n}",
