  "bg-shape-grid-glow-center": "/* Base Technical Grid Layer */\n.bg-shape-grid-glow-center::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-glow-center::after {\r\n  inset: 0;\r\n  background: radial-gradient(ellipse at 50% 45%, rgba(var(--bg-shape-color), 0.10), transparent 65%);\r\n}",
