  "bg-shape-grid-frame": "/* Base Technical Grid Layer */\n.bg-shape-grid-frame::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-frame::after {\r\n  inset: 2.5rem;\r\n  border: 1px solid rgba(var(--bg-shape-color), 0.12);\r\n  box-shadow: inset 0 0 5rem rgba(var(--bg-shape-color), 0.025);\r\n}",
  "bg-shape-grid-diagonal": "/* Base Technical Grid Layer */\n.bg-shape-grid-diagonal::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-diagonal::after {\r\n  inset: -30%;\r\n  background: linear-gradient(135deg, transparent 30%, rgba(var(--bg-shape-color), 0.09) 50%, transparent 70%);\r\n}",
  "bg-shape-grid-wave": "/* Base Technical Grid Layer */\n.bg-shape-grid-wave::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-wave::after {\r\n  inset: 0;\r\n  background: repeating-radial-gradient(\r\n    ellipse at 100% 0%,\r\n    transparent 0 2rem,\r\n    rgba(var(--bg-shape-color), 0.08) 2.05rem 2.1rem,\r\n    transparent 2.15rem 3rem\r\n  );\r\n  mask-image: linear-gradient(135deg, #000, transparent 80%);\r\n  -webkit-mask-image: linear-gradient(135deg, #000, transparent 80%);\r\n}",
  "bg-shape-grid-radial-tr": "/* Base Technical Grid Layer */\n.bg-shape-grid-radial-tr::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-radial-tr::after {\r\n  width: 38rem;\r\n  height: 38rem;\r\n  right: -13rem;\r\n  top: -20rem;\r\n  border-radius: 50%;\r\n  background: repeating-conic-gradient(\r\n    from 0deg,\r\n    rgba(var(--bg-shape-color), 0.065) 0deg 0.5deg,\r\n    transparent 0.5deg 15deg\r\n  );\r\n  mask-image: radial-gradient(circle, #000, transparent 68%);\r\n  -webkit-mask-image: radial-gradient(circle, #000, transparent 68%);\r\n}",
  "bg-shape-grid-rings-tr": "/* Base Technical Grid Layer */\n.bg-shape-grid-rings-tr::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-rings-tr::after {\r\n  width: 30rem;\r\n  height: 30rem;\r\n  right: -12rem;\r\n  top: -16rem;\r\n  border-radius: 50%;\r\n  border: 1px solid rgba(var(--bg-shape-color), 0.17);\r\n  box-shadow:\r\n    0 0 0 2rem rgba(var(--bg-shape-color), 0.025),\r\n    0 0 0 4rem rgba(var(--bg-shape-color), 0.025),\r\n    0 0 0 6rem rgba(var(--bg-shape-color), 0.018);\r\n}",
  "bg-shape-grid-rings-center": "/* Base Technical Grid Layer */\n.bg-shape-grid-rings-center::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-rings-center::after {\r\n  width: 28rem;\r\n  height: 28rem;\r\n  top: 50%;\r\n  left: 50%;\r\n  transform: translate(-50%, -50%);\r\n  border-radius: 50%;\r\n  border: 1px solid rgba(var(--bg-shape-color), 0.13);\r\n  box-shadow:\r\n    0 0 0 2rem rgba(var(--bg-shape-color), 0.02),\r\n    0 0 0 4rem rgba(var(--bg-shape-color), 0.02),\r\n    0 0 0 6rem rgba(var(--bg-shape-color), 0.015);\r\n}",
  "bg-shape-grid-circles": "/* Base Technical Grid Layer */\n.bg-shape-grid-circles::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-circles::after {\r\n  width: 32rem;\r\n  height: 32rem;\r\n  right: -10rem;\r\n  top: -15rem;\r\n  border-radius: 50%;\r\n  border: 1px solid rgba(var(--bg-shape-color), 0.15);\r\n  box-shadow:\r\n    0 0 0 3rem rgba(var(--bg-shape-color), 0.018),\r\n    0 0 0 6rem rgba(var(--bg-shape-color), 0.018);\r\n}",
  "bg-shape-grid-squares-tr": "/* Base Technical Grid Layer */\n.bg-shape-grid-squares-tr::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-squares-tr::after {\r\n  width: 19rem;\r\n  height: 19rem;\r\n  right: -7rem;\r\n  top: -8rem;\r\n  border: 1px solid rgba(var(--bg-shape-color), 0.17);\r\n  transform: rotate(25deg);\r\n  box-shadow:\r\n    0 0 0 1.5rem rgba(var(--bg-shape-color), 0.018),\r\n    0 0 0 3rem rgba(var(--bg-shape-color), 0.018);\r\n}",
  "bg-shape-grid-orbit-tr": "/* Base Technical Grid Layer */\n.bg-shape-grid-orbit-tr::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-orbit-tr::after {\r\n  width: 34rem;\r\n  height: 17rem;\r\n  right: -9rem;\r\n  top: -5rem;\r\n  border: 1px solid rgba(var(--bg-shape-color), 0.18);\r\n  border-radius: 50%;\r\n  transform: rotate(-35deg);\r\n  box-shadow: 0 0 0 2rem rgba(var(--bg-shape-color), 0.018);\r\n}",
  "bg-shape-grid-blob-tr": "/* Base Technical Grid Layer */\n.bg-shape-grid-blob-tr::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-blob-tr::after {\r\n  width: 34rem;\r\n  height: 28rem;\r\n  right: -9rem;\r\n  top: -11rem;\r\n  border-radius: 60% 40% 35% 65% / 55% 45% 65% 35%;\r\n  transform: rotate(-20deg);\r\n  background: radial-gradient(\r\n    ellipse at center,\r\n    rgba(var(--bg-shape-color), 0.14),\r\n    rgba(var(--bg-shape-color), 0.045) 55%,\r\n    transparent 76%\r\n  );\r\n}",
  "bg-shape-grid-dots-tr": "/* Base Technical Grid Layer */\n.bg-shape-grid-dots-tr::before {\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(var(--bg-shape-color, 100, 116, 139), 0.18) 1px, transparent 1px);\n  background-size: 3.25rem 3.25rem;\n}\n\n.bg-shape-grid-dots-tr::after {\r\n  width: 20rem;\r\n  height: 20rem;\r\n  right: -3rem;\r\n  top: -5rem;\r\n  background-image: radial-gradient(rgba(var(--bg-shape-color), 0.22) 1.5px, transparent 2px);\r\n  background-size: 1.4rem 1.4rem;\r\n  mask-image: radial-gradient(circle at center, #000, transparent 72%);\r\n  -webkit-mask-image: radial-gradient(circle at center, #000, transparent 72%);\r\n}",
