  "bg-shape-text": ".bg-shape-text::before {\r\n  content: \"Outline text\";\r\n  left: 50%;\r\n  top: 0;\r\n  transform: translateX(-50%);\r\n  display: block;\r\n  font-family: Urbanist, Georgia, \"Times New Roman\", serif;\r\n  font-size: clamp(4.75rem, 13vw, 10.5rem);\r\n  font-weight: 800;\r\n  letter-spacing: -0.06em;\r\n  line-height: 0.8;\r\n  white-space: nowrap;\r\n  color: rgba(var(--bg-shape-color), 0.12);\r\n  -webkit-text-fill-color: rgba(var(--bg-shape-color), 0.12);\r\n  -webkit-text-stroke: 2px rgba(var(--bg-shape-color), 0.38);\r\n  paint-order: stroke fill;\r\n  user-select: none;\r\n}",
