  "bg-shape-motion-lava-lamp": ".bg-shape-motion-lava-lamp::before {\n  width: 22rem;\n  height: 22rem;\n  right: -3rem;\n  top: 15%;\n  border-radius: 65% 35% 45% 55% / 55% 45% 55% 45%;\n  background: radial-gradient(circle at 40% 40%, rgba(var(--bg-shape-color), 0.22) 0%, rgba(var(--bg-shape-color), 0.06) 60%, transparent 75%);\n  animation: motionLavaFloat1 12s ease-in-out infinite alternate;\n}\n.bg-shape-motion-lava-lamp::after {\n  width: 16rem;\n  height: 16rem;\n  right: 15%;\n  top: -4rem;\n  border-radius: 40% 60% 60% 40% / 60% 30% 70% 40%;\n  background: radial-gradient(circle at 40% 40%, rgba(var(--bg-shape-color), 0.18) 0%, transparent 70%);\n  animation: motionLavaFloat2 9s ease-in-out infinite alternate;\n}\n@keyframes motionLavaFloat1 { 0% { transform: translate(0, 0) scale(1); } 100% { transform: translate(-40px, -60px) scale(1.12); } }\n@keyframes motionLavaFloat2 { 0% { transform: translate(0, 0) scale(1); } 100% { transform: translate(30px, 70px) scale(0.9); } }",
